    originStory:
      "Written in Eilenburg, Germany, during the catastrophic Thirty Years' War. As the city was devastated by famine and the Black Plague, Pastor Rinkart had to conduct as many as 40 to 50 burials a day, including his own wife. In the midst of overwhelming grief and devastation, Rinkart turned to God with defiant praise, penning this majestic thanksgiving anthem for his family before meals. Translated by Catherine Winkworth, it is sung worldwide as an emblem of unshakeable gratitude.",
    spiritualTakeaway:
      "Thanksgiving is not a reaction to easy circumstances; it is an act of relentless faith in God's eternal goodness amidst hardship.",
