  // K&S 206 (id: 252): Gbo ẹda ọrun ń kọrin (Hark! The Herald Angels Sing)
  252: {
    hymnId: 252,
    hymnNumber: "K&S 206",
    category: "general_classic",
    title: "Gbo ẹda ọrun ń kọrin (Hark! The Herald Angels Sing)",
    author: "Charles Wesley & Felix Mendelssohn",
    year: "1739/1840",
    scriptureReference: "Luke 2:13–14 — \"Glory to God in the highest, and on earth peace, good will toward men.\"",
    originStory:
      "Charles Wesley wrote the original poem beginning \"Hark how all the welkin rings\" in 1739. Evangelist George Whitefield altered the opening couplet to \"Hark! the herald angels sing, Glory to the newborn King.\" In 1855, English organist William Cummings adapted Mendelssohn's celebratory chorus to Wesley's carol, creating the world's most jubilant Christmas proclamation.",
    spiritualTakeaway:
      "In the incarnation, God reconciled fallen humanity to Himself; Christ is our Prince of Peace and Sun of Righteousness.",
  },

  // K&S 209 (id: 255): Ajin jin oru mimọ (Silent Night, Holy Night / Stille Nacht)
  255: {
    hymnId: 255,
    hymnNumber: "K&S 209",
    category: "general_classic",
    title: "Ajin jin oru mimọ (Silent Night, Holy Night / Stille Nacht)",
    author: "Father Joseph Mohr & Franz Xaver Gruber",
    year: "1818",
    scriptureReference: "Luke 2:8–14 — \"And there were in the same country shepherds abiding in the field, keeping watch over their flock by night.\"",
    originStory:
      "Written on Christmas Eve 1818 in the Austrian village of Oberndorf. When the church organ at St. Nicholas was flooded and unusable, Father Mohr rushed a poem he had written to schoolteacher and organist Gruber, requesting a guitar melody for midnight Christmas Eve mass. The song traveled across Europe and was sung simultaneously in English and German trenches during the famous 1914 World War I Christmas truce.",
    spiritualTakeaway:
      "The quiet stillness of Christ's nativity speaks a peace far louder than all the turmoil of a raging world.",
  },

  // K&S 210 (id: 256): Apata ayérayé (O God, the Rock of Ages)
