    scriptureReference: "Psalm 23:6 — \"Surely goodness and mercy shall follow me all the days of my life: and I will dwell in the house of the LORD for ever.\"",
    originStory:
      "Sir Henry Baker, primary editor of 'Hymns Ancient and Modern', wrote this tender paraphrase of Psalm 23. His dying words on his deathbed in 1877 were the third stanza of this very hymn: 'Perverse and foolish oft I strayed, But yet in love He sought me, And on His shoulder gently laid, And home, rejoicing, brought me.'",
    spiritualTakeaway:
      "Even when we foolishly wander, the Good Shepherd never abandons us; in tender love He seeks us and brings us safely home.",
