    scriptureReference: "Galatians 6:7 — \"For whatsoever a man soweth, that shall he also reap.\"",
    originStory:
      "In 1877, a young man who had lived a worldly, wasteful life was converted on his deathbed in Providence, Rhode Island. As he lay dying, he wept bitterly, not out of fear of death—for he knew Christ had forgiven him—but because he had won no souls for his Lord, crying: 'Must I go with empty hands?' Evangelist Charles C. Luther recorded those agonizing words, and George Stebbins set them to music.",
    spiritualTakeaway:
      "While salvation is God's free gift, our days on earth are a precious opportunity to labor and win souls for Christ's eternal kingdom.",
